def build_content(module_number, item, next_title):
    return (
        f"Introduction\n{item['theory']}\n\n"
        "Learning objectives\n"
        f"- Explain {item['title'].lower()} using correct C terminology.\n"
        "- Read, modify, compile, and test a complete portable C11 program.\n"
        "- Predict output and identify a boundary or failure case.\n\n"
        "Prerequisites\n"
        f"Complete the earlier lessons in Module {module_number} and use a compiler with -std=c11 -Wall -Wextra -Wpedantic.\n\n"
        "Detailed theory and syntax\n"
        f"{item['theory']}\n\nThe syntax in this lesson is shown by the complete program below. Prefer explicit names, checked return values, bounded storage, and one responsibility per function.\n\n"
        "Complete C example\n```c\n"
        f"{item['code']}\n```\n\n"
        "Expected output\n```text\n"
        f"{item['output']}\n```\n\n"
        "Line-by-line explanation\n"
        f"{item['explanation']} The include lines declare the standard operations used by the example; main controls execution; each statement has a deliberate role; and return 0 reports success.\n\n"
        "Common beginner mistakes\n"
        "- Ignoring compiler warnings or changing many lines before retesting.\n"
        "- Using an object outside its lifetime or outside an array's valid bounds.\n"
        "- Assuming input, allocation, or file operations cannot fail.\n"
        "- Copying an example without explaining its assumptions and expected output.\n\n"
        "Practice exercises\n"
        f"1. Re-type and compile the example, then change one input or constant and predict the new output.\n"
        f"2. Explain the boundary or failure case implied by {item['title'].lower()} and write a test for it.\n"
        "3. Add one clear comment explaining why the program is safe and rerun the strict compiler command.\n\n"
        "Myanmar explanation\n"
        f"{item['mm']}\n\nSummary\n"
        f"You practiced {item['title'].lower()} with a complete C example, expected output, testing guidance, and a safety-focused explanation.\n\nNext lesson\n{next_title}\n"
    )


def seed_modules_4_to_20(db, modules_by_position):
    from .models import CodeExample, Lesson, LessonQuiz, QuizQuestion
    for module_number, module in modules_by_position.items():
        items = MODULES_4_TO_20[module_number]
        for position, item in enumerate(items, 1):
            next_title = items[position]["title"] if position < len(items) else "Continue to the next module."
            slug = f"{module_number:02d}-{item['title'].lower().replace(' ', '-')[:70]}"
            lesson = db.scalar(select(Lesson).where(Lesson.module_id == module.id, Lesson.order_index == position))
            if not lesson:
                lesson = Lesson(module_id=module.id, title=item["title"], slug=slug, description=item["theory"][:240], content_en="", order_index=position, duration_minutes=30, status="published", published=True)
                db.add(lesson); db.flush()
            lesson.title = item["title"]; lesson.slug = slug; lesson.description = item["theory"][:240]
            lesson.content_en = build_content(module_number, item, next_title); lesson.content_mm = item["mm"]
            lesson.duration_minutes = 30; lesson.status = "published"; lesson.published = True
            example = db.scalar(select(CodeExample).where(CodeExample.lesson_id == lesson.id, CodeExample.position == 1))
            if not example:
                example = CodeExample(lesson_id=lesson.id, position=1); db.add(example)
            example.title = f"{item['title']} — complete example"; example.language = "c"; example.filename = "main.c"; example.code = item["code"]
            example.description = f"Expected output:\n{item['output']}\n\nLine-by-line explanation:\n{item['explanation']}"
            quiz = db.scalar(select(LessonQuiz).where(LessonQuiz.lesson_id == lesson.id))
            if not quiz:
                quiz = LessonQuiz(lesson_id=lesson.id, title=f"Module {module_number} review: {item['title']}", explanation="Review the answer explanations and compile the example again before retrying."); db.add(quiz); db.flush()
            quiz.title = f"Module {module_number} review: {item['title']}"; quiz.explanation = "Review the answer explanations and compile the example again before retrying."; quiz.status = "published"
            existing = {q.position: q for q in db.scalars(select(QuizQuestion).where(QuizQuestion.quiz_id == quiz.id)).all()}
            for question_position, question_data in enumerate(item["questions"], 1):
                prompt, options, answer, explanation, question_type = question_data
                question = existing.get(question_position)
                if not question:
                    question = QuizQuestion(quiz_id=quiz.id, position=question_position); db.add(question)
                question.prompt = prompt; question.options_json = json.dumps(options); question.correct_answer = answer; question.explanation = explanation; question.question_type = question_type; question.position = question_position
            for stale_position, stale in existing.items():
                if stale_position > len(item["questions"]): db.delete(stale)
